function useApiList<T>(endpoint: string, key: string) {
  const [state, setState] = useState<{ items: T[]; loading: boolean; error: string | null }>({ items: [], loading: true, error: null });
  useEffect(() => {
    const controller = new AbortController();
    setState((current) => ({ ...current, loading: true, error: null }));
    fetch(`${endpoint}${endpoint.includes("?") ? "&" : "?"}_=${key}`, { signal: controller.signal, headers: { Accept: "application/json" } })
      .then(async (response) => { const payload = await response.json() as ApiResponse<{ items?: T[] }>; if (!response.ok) throw new Error(payload.error?.message || "Unable to load data."); return payload.data?.items || []; })
      .then((items) => setState({ items, loading: false, error: null }))
      .catch((error: unknown) => { if (error instanceof DOMException && error.name === "AbortError") return; setState({ items: [], loading: false, error: error instanceof Error ? error.message : "Unable to load data." }); });
    return () => controller.abort();
  }, [endpoint, key]);
  return state;
}

function PrimaryButton({ children, onClick, className = "" }: { children: React.ReactNode; onClick?: () => void; className?: string }) { return <button onClick={onClick} className={cn("inline-flex h-9 items-center justify-center gap-2 rounded-lg bg-gradient-to-r from-[#6937e7] to-[#7445ed] px-3.5 text-xs font-bold text-white shadow-[0_5px_13px_rgba(105,55,231,.2)] transition hover:brightness-105 focus:outline-none focus:ring-4 focus:ring-[#e8e2ff]", className)}>{children}</button>; }
function SecondaryButton({ children, onClick, className = "" }: { children: React.ReactNode; onClick?: () => void; className?: string }) { return <button onClick={onClick} className={cn("inline-flex h-9 items-center justify-center gap-2 rounded-lg border border-[#dfe3ea] bg-white px-3.5 text-xs font-bold text-[#34415b] transition hover:border-[#c7cce0] hover:bg-[#fafbff] focus:outline-none focus:ring-4 focus:ring-[#eeeaff]", className)}>{children}</button>; }
function LinkButton({ children, onClick }: { children: React.ReactNode; onClick?: () => void }) { return <button onClick={onClick} className="inline-flex items-center gap-1 text-xs font-bold text-[#5e3cdb] hover:text-[#3e259d]">{children}<ArrowRight size={14} /></button>; }
function MetricCard({ metric, compact = false }: { metric: MetricKpi; compact?: boolean }) { return <Card className={cn("min-w-0", compact ? "p-3" : "p-4")}><div className="flex items-start justify-between gap-2"><span className="text-[11px] font-medium text-[#58657d]">{metric.label}</span><KpiIcon type={metric.icon} tone={metric.tone} /></div><div className="mt-2 text-[24px] font-extrabold tracking-[-.045em] text-[#10192d]">{metric.value}</div><div className={cn("mt-1 flex items-center gap-1 text-[10px] font-bold", metric.trend === "down" ? "text-[#eb505c]" : "text-[#159a65]")}>{metric.trend === "down" ? <ArrowDownRight size={12} /> : <ArrowUpRight size={12} />} {metric.change}<span className="font-medium text-[#8691a4]">vs Apr 1 – Apr 30</span></div></Card>; }
function SectionCardTitle({ title, description, action }: { title: string; description?: string; action?: React.ReactNode }) { return <div className="flex items-start justify-between gap-3"><div><h2 className="text-[14px] font-extrabold text-[#111a2e]">{title}</h2>{description && <p className="mt-1 text-[11px] text-[#7d899e]">{description}</p>}</div>{action}</div>; }
function Field({ label, placeholder, value, type = "text", className = "", onChange }: { label: string; placeholder?: string; value?: string; type?: string; className?: string; onChange?: (event: React.ChangeEvent<HTMLInputElement>) => void }) { return <label className={className}><span className="mb-1.5 block text-xs font-bold text-[#28354d]">{label}</span><input type={type} defaultValue={value} onChange={onChange} placeholder={placeholder} className="h-10 w-full rounded-lg border border-[#dfe3eb] px-3 text-xs text-[#28354d] outline-none placeholder:text-[#a0a9b8] focus:border-[#9d8af5] focus:ring-4 focus:ring-[#f0edff]" /></label>; }

function PlatformSpendCard() { return <Card><SectionCardTitle title="Spend by Platform" /><div className="mt-2 flex items-center gap-3"><div className="w-[49%] min-w-0"><DonutChart data={spendChartData} total="$24,500" label="Total Spend" /></div><div className="min-w-0 flex-1 space-y-3">{platformSpend.map((item) => <div className="flex items-center justify-between gap-2 text-[11px]" key={item.label}><div className="flex min-w-0 items-center gap-2"><PlatformIcon platform={item.label.replace(" Ads", "")} size={19} /><span className="truncate font-semibold text-[#43506a]">{item.label}</span></div><div className="shrink-0 text-right"><span className="block font-bold text-[#202b41]">{money(item.value)}</span><span className="text-[10px] text-[#8490a4]">{item.percent}%</span></div></div>)}</div></div></Card>; }

function CampaignTable({ compact = false, data = campaigns }: { compact?: boolean; data?: Campaign[] }) {
  const router = useRouter(); const [query, setQuery] = useState(""); const rows = data.filter((item) => item.name.toLowerCase().includes(query.toLowerCase())).slice(0, compact ? 5 : data.length);
  return <Card flush><div className="flex flex-wrap items-center justify-between gap-3 border-b border-[#edf0f4] p-4 sm:p-5"><SectionCardTitle title={compact ? "Top Campaigns" : "All Campaigns"} description={compact ? undefined : "Manage and monitor all your marketing campaigns."} action={compact ? <LinkButton onClick={() => router.push("/campaigns")}>View All Campaigns</LinkButton> : undefined} />{!compact && <div className="flex items-center gap-2"><div className="relative hidden sm:block"><Search size={14} className="absolute left-2.5 top-2.5 text-[#8b96aa]" /><input value={query} onChange={(event) => setQuery(event.target.value)} placeholder="Search campaigns..." className="h-9 w-48 rounded-lg border border-[#e1e5ec] pl-8 pr-2 text-xs outline-none focus:border-[#9e8af5]" /></div><SecondaryButton><Filter size={14} />Filters</SecondaryButton><SecondaryButton className="px-2.5"><MoreHorizontal size={16} /></SecondaryButton></div>}</div><div className="overflow-x-auto"><table className="w-full min-w-[850px] text-left"><thead><tr className="border-b border-[#edf0f4] text-[10px] font-bold uppercase tracking-[.03em] text-[#8590a4]"><th className="px-4 py-3 sm:px-5">Campaign</th><th className="px-4 py-3">Platform</th><th className="px-4 py-3">Status</th><th className="px-4 py-3">Budget</th><th className="px-4 py-3">Spend</th><th className="px-4 py-3">Conversions</th><th className="px-4 py-3">ROAS</th><th className="px-4 py-3">Actions</th></tr></thead><tbody>{rows.map((campaign) => <tr key={campaign.id} className="border-b border-[#f0f2f6] text-xs last:border-0 hover:bg-[#fbfbfe]"><td className="px-4 py-3 sm:px-5"><button onClick={() => router.push(`/campaigns/${campaign.id}`)} className="flex items-center gap-2.5 text-left"><PlatformIcon platform={campaign.platform} size={24} /><span><span className="block font-bold text-[#17223a]">{campaign.name}</span><span className="mt-0.5 block text-[10px] text-[#8390a5]">{campaign.objective} Campaign</span></span></button></td><td className="px-4 py-3"><PlatformIcon platform={campaign.platform} size={25} /></td><td className="px-4 py-3"><StatusBadge status={campaign.status} /></td><td className="px-4 py-3 font-semibold text-[#4c5a73]">{money(campaign.budget)}/day</td><td className="px-4 py-3 font-bold text-[#26334b]">{money(campaign.spend)}</td><td className="px-4 py-3 font-semibold text-[#4c5a73]">{campaign.conversions.toLocaleString()}</td><td className="px-4 py-3"><span className="font-bold text-[#219b69]">{campaign.roas.toFixed(2)} <ArrowUpRight size={12} className="inline" /></span></td><td className="px-4 py-3"><div className="flex items-center gap-1"><button aria-label="View analytics" onClick={() => router.push(`/campaigns/${campaign.id}`)} className="rounded-md border border-[#e5e8ee] p-1.5 text-[#67758e] hover:text-[#5e3cdb]"><BarChart3 size={13} /></button><button aria-label="Edit campaign" className="rounded-md border border-[#e5e8ee] p-1.5 text-[#67758e] hover:text-[#5e3cdb]"><Edit3 size={13} /></button><MoreHorizontal size={15} className="text-[#67758e]" /></div></td></tr>)}</tbody></table></div>{!compact && <div className="flex items-center justify-between border-t border-[#edf0f4] px-4 py-3 text-[11px] text-[#7d899e]"><span>Showing 1 to {rows.length} of 23 campaigns</span><div className="flex items-center gap-1"><button className="rounded-md border border-[#e2e5ec] p-1.5"><ChevronLeft size={13} /></button><button className="rounded-md bg-[#6940e8] px-2.5 py-1.5 font-bold text-white">1</button><button className="rounded-md border border-[#e2e5ec] px-2.5 py-1.5">2</button><button className="rounded-md border border-[#e2e5ec] px-2.5 py-1.5">3</button><button className="rounded-md border border-[#e2e5ec] p-1.5"><ChevronRight size={13} /></button></div></div>}</Card>;
}

function InsightsCard() { const icons = [ArrowUpRight, Lightbulb, CircleHelp, TrendingUp]; return <Card flush><div className="flex items-center justify-between border-b border-[#edf0f4] p-4 sm:p-5"><div className="flex items-center gap-2"><span className="grid h-7 w-7 place-items-center rounded-lg bg-[#f0eaff] text-[#6940e8]"><Sparkles size={15} /></span><h2 className="text-[14px] font-extrabold text-[#111a2e]">AI Insights</h2></div><LinkButton>View All</LinkButton></div><div className="divide-y divide-[#edf0f4]">{insights.map((insight, index) => { const Icon = icons[index % icons.length]; return <button key={insight.id} className="flex w-full gap-3 p-4 text-left transition hover:bg-[#fbfbff]"><span className={cn("mt-0.5 grid h-8 w-8 shrink-0 place-items-center rounded-full", insight.tone === "green" ? "bg-[#e6f8ee] text-[#159a65]" : insight.tone === "orange" ? "bg-[#fff2de] text-[#e99a23]" : insight.tone === "blue" ? "bg-[#e9f3ff] text-[#2783de]" : "bg-[#f0eaff] text-[#6940e8]")}><Icon size={15} /></span><span><span className="block text-xs font-bold text-[#24324b]">{insight.title}</span><span className="mt-1 block text-[10px] leading-4 text-[#7b879b]">{insight.description}</span></span></button>; })}</div></Card>; }
function IntegrationsCard() { const router = useRouter(); return <Card><SectionCardTitle title="Integrations" action={<LinkButton onClick={() => router.push("/integrations")}>View All</LinkButton>} /><div className="mt-4 space-y-2">{integrations.slice(0, 5).map((item) => <div className="flex items-center gap-3 border-b border-[#f0f2f6] py-2.5 last:border-0" key={item.id}><PlatformIcon platform={item.platform} size={22} /><span className="min-w-0 flex-1 truncate text-xs font-semibold text-[#35415a]">{item.platform}</span><StatusBadge status={item.status === "Not connected" ? "Draft" : "Connected"} /></div>)}</div><SecondaryButton onClick={() => router.push("/integrations")} className="mt-3 w-full text-[#5e3cdb]">Add New Integration</SecondaryButton></Card>; }
function QuickStart() { const router = useRouter(); return <Card><SectionCardTitle title="Create New Campaign" /><p className="mt-1 text-[11px] text-[#7b879c]">Choose a platform to create your campaign</p><div className="mt-5 flex flex-wrap gap-2">{["Google Ads", "Meta Ads", "Instagram", "LinkedIn", "TikTok"].map((platform) => <button onClick={() => router.push("/campaigns/create")} key={platform} className="grid h-12 w-12 place-items-center rounded-lg border border-[#e5e8ef] hover:border-[#b7aaf9]"><PlatformIcon platform={platform} size={28} /></button>)}<button onClick={() => router.push("/campaigns/create")} className="flex h-12 items-center gap-1 rounded-lg border border-[#e5e8ef] px-3 text-xs font-semibold text-[#6a7488]"><Plus size={14} />More</button></div></Card>; }

function CampaignsPage() { const router = useRouter(); const [tab, setTab] = useState("All Campaigns"); const resource = useApiList<Campaign>("/api/v1/campaigns", "campaigns"); const filtered = resource.items.filter((item) => tab === "All Campaigns" || item.status === tab.slice(0, -1)); return <AppShell title="Campaigns" action={<PrimaryButton onClick={() => router.push("/campaigns/create")}><Plus size={15} />Create Campaign<ChevronDown size={13} /></PrimaryButton>}><PageHeading title="Campaigns" description="Manage and monitor all your marketing campaigns in one place." /><div className="grid gap-3 md:grid-cols-2 xl:grid-cols-5">{kpis.slice(0, 4).map((metric) => <MetricCard key={metric.label} metric={metric} />)}</div>{resource.error && <div className="mt-4 rounded-lg border border-[#f2c4c8] bg-[#fff8f8] p-3 text-xs text-[#b72e38]">{resource.error}</div>}<Card flush className="mt-4"><div className="flex flex-wrap items-center justify-between gap-3 border-b border-[#edf0f4] px-4 pt-4 sm:px-5"><Tabs items={["All Campaigns", "Active", "Paused", "Draft", "Completed", "Archived"]} active={tab} onChange={setTab} /><div className="flex gap-2 pb-3"><SecondaryButton>May 1 – May 31 <CalendarDays size={13} /></SecondaryButton><SecondaryButton className="hidden sm:inline-flex">All Platforms <ChevronDown size={13} /></SecondaryButton></div></div><div className="p-4 sm:p-5"><CampaignTable data={filtered} /></div></Card><div className="mt-4 grid gap-4 xl:grid-cols-[minmax(0,.95fr)_minmax(0,1.4fr)]">{filtered[0] ? <CampaignSummary campaign={filtered[0]} /> : <Card><SectionCardTitle title={resource.loading ? "Loading campaigns" : "No campaigns yet"} description="Create a campaign to start collecting performance data." /></Card>}<Card><SectionCardTitle title="Performance Over Time" action={<SecondaryButton className="h-8">Daily<ChevronDown size={13} /></SecondaryButton>} /><div className="mt-3"><TrendChart data={chartSeries} compact /></div></Card></div></AppShell>; }
function CampaignSummary({ campaign }: { campaign: Campaign }) { return <Card><div className="flex items-start justify-between"><div className="flex items-center gap-2"><PlatformIcon platform={campaign.platform} size={28} /><div><h2 className="text-[16px] font-extrabold text-[#111a2e]">{campaign.name}</h2><p className="mt-0.5 text-[11px] text-[#7b879c]">{campaign.platform} {campaign.objective} Campaign</p></div></div><StatusBadge status={campaign.status} /></div><div className="mt-5 grid grid-cols-2 gap-x-5 gap-y-4 border-t border-[#edf0f4] pt-4 text-xs sm:grid-cols-4">{[["Budget", "$5,000 /day"], ["Start Date", "May 01, 2024"], ["End Date", "May 31, 2024"], ["Objective", "Sales"]].map(([label, value]) => <div key={label}><div className="text-[10px] text-[#8792a6]">{label}</div><div className="mt-1 font-bold">{value}</div></div>)}</div><div className="mt-5 border-t border-[#edf0f4] pt-4"><div className="text-xs font-bold">Campaign Description</div><p className="mt-1 text-[11px] leading-5 text-[#7b879c]">This campaign targets high-intent keywords to drive sales during our summer sale event.</p></div></Card>; }

function AnalyticsPage() { const cost: MetricKpi = { label: "Cost / Conversion", value: "$6.51", change: "3.2%", trend: "down", icon: "spend", tone: "orange" }; const metrics: MetricKpi[] = [{ ...kpis[0], label: "Total Spend" }, { ...kpis[1], label: "Total Clicks" }, { ...kpis[2], label: "Conversions" }, cost, { ...kpis[3], label: "ROAS" }, { ...kpis[4], label: "CTR" }]; return <AppShell title="Analytics"><PageHeading title="Analytics" description="Track performance across all your campaigns and platforms." action={<div className="flex gap-2"><SecondaryButton>May 1 – May 31 <CalendarDays size={13} /></SecondaryButton><SecondaryButton className="hidden sm:inline-flex">All Platforms<ChevronDown size={13} /></SecondaryButton><SecondaryButton><Filter size={13} />Filters</SecondaryButton></div>} /><div className="grid gap-3 md:grid-cols-2 xl:grid-cols-6">{metrics.map((metric) => <MetricCard key={metric.label} metric={metric} compact />)}</div><div className="mt-4 grid gap-4 xl:grid-cols-[minmax(0,2fr)_minmax(340px,1fr)]"><Card><SectionCardTitle title="Performance Over Time" action={<SecondaryButton className="h-8">Daily<ChevronDown size={13} /></SecondaryButton>} /><div className="mt-3"><TrendChart data={chartSeries} showRoas /></div></Card><Card><SectionCardTitle title="Performance by Platform" /><div className="mt-4"><DonutChart data={spendChartData} total="$24,500" label="Total Spend" /></div><div className="space-y-2">{platformSpend.map((item) => <div className="flex items-center justify-between text-xs" key={item.label}><span className="flex items-center gap-2"><PlatformIcon platform={item.label.replace(" Ads", "")} size={18} />{item.label}</span><strong>{money(item.value)} <span className="font-normal text-[#8490a4]">({item.percent}%)</span></strong></div>)}</div></Card></div><div className="mt-4 grid gap-4 xl:grid-cols-[minmax(0,1.5fr)_minmax(300px,.75fr)_minmax(300px,.9fr)]"><CampaignTable compact /><Card><SectionCardTitle title="Key Metrics Funnel" /><FunnelChart /><LinkButton>View full funnel report</LinkButton></Card><DataTableCard title="Top Performing Keywords" /></div><Card className="mt-4"><SectionCardTitle title="Analytics Insights" action={<LinkButton>View all insights</LinkButton>} /><div className="mt-4 grid gap-3 md:grid-cols-4">{insights.map((item) => <div className="flex gap-2 border-r border-[#edf0f4] pr-3 last:border-0" key={item.id}><KpiIcon type="sparkles" tone={item.tone} /><div><div className="text-xs font-bold">{item.title}</div><p className="mt-1 text-[10px] leading-4 text-[#7e899e]">{item.description}</p></div></div>)}</div></Card></AppShell>; }
function DataTableCard({ title }: { title: string }) { const rows = [["summer sale", "4,125", "142", "$4.32"], ["buy online", "3,245", "98", "$5.12"], ["best deals online", "2,987", "76", "$4.89"], ["discount offers", "2,421", "64", "$5.21"]]; return <Card><SectionCardTitle title={title} /><div className="mt-3 overflow-x-auto"><table className="w-full min-w-[300px] text-left text-[10px]"><thead><tr className="border-b border-[#edf0f4] text-[#8792a6]"><th className="pb-2">Keyword</th><th className="pb-2">Clicks</th><th className="pb-2">Conversions</th><th className="pb-2">Cost / Conv.</th></tr></thead><tbody>{rows.map((row) => <tr className="border-b border-[#f0f2f6] last:border-0" key={row[0]}>{row.map((cell, index) => <td className={cn("py-2.5", index === 0 && "font-bold text-[#27344d]")} key={`${row[0]}-${index}`}>{cell}</td>)}</tr>)}</tbody></table></div><div className="mt-3"><LinkButton>View all keywords</LinkButton></div></Card>; }

function IntegrationsPage({ detailId }: { detailId?: string }) { const [filter, setFilter] = useState("All Platforms"); const resource = useApiList<Integration>("/api/v1/integrations", detailId || "integrations"); const filtered = resource.items.filter((item) => filter === "All Platforms" || item.category === filter); return <AppShell title="Integrations"><PageHeading title={detailId ? "Integration Details" : "Connect Your Marketing Platforms"} description="Connect your accounts to import data, manage campaigns and get AI-powered insights." action={<SecondaryButton onClick={() => window.location.reload()}><RefreshCw size={14} />Refresh Status</SecondaryButton>} /><div className="mb-4 flex gap-2 overflow-x-auto">{["All Platforms", "Advertising", "Analytics", "Social Media", "E-commerce", "Others"].map((item) => <button onClick={() => setFilter(item)} className={cn("whitespace-nowrap rounded-lg border px-3.5 py-2 text-xs font-bold", filter === item ? "border-[#6a3ce8] bg-[#6940e8] text-white" : "border-[#e1e4ec] bg-white text-[#5b687f]")} key={item}>{item}</button>)}</div><div className="grid gap-4 xl:grid-cols-[minmax(0,1fr)_310px]"><div className="space-y-3">{resource.error && <Card className="border-[#f2c4c8] text-xs text-[#b72e38]">{resource.error}</Card>}{resource.loading && <Card className="text-xs text-[#7d899e]">Loading integrations…</Card>}{filtered.map((item) => <IntegrationRow item={item} key={item.id} />)}</div><div className="space-y-4"><Card><SectionCardTitle title="Why connect platforms?" /><div className="mt-4 rounded-lg bg-[#faf9ff] p-4"><div className="grid h-24 place-items-center"><BarChart3 className="text-[#7a56e9]" size={70} /></div></div><div className="mt-4 space-y-3 text-xs"><p><Check className="mr-2 inline text-[#20ad78]" size={14} />Unified dashboard for all campaigns</p><p><Check className="mr-2 inline text-[#20ad78]" size={14} />AI-powered recommendations</p><p><Check className="mr-2 inline text-[#20ad78]" size={14} />Automated reporting</p></div></Card><Card><SectionCardTitle title="Secure & Reliable" /><div className="mx-auto mt-4 grid h-14 w-14 place-items-center rounded-full bg-[#f1edff] text-[#6940e8]"><ShieldCheck size={25} /></div><p className="mt-4 text-center text-xs leading-5 text-[#718098]">We use industry-standard encryption and never store your passwords.</p></Card></div></div></AppShell>; }
function IntegrationRow({ item }: { item: Integration }) { const router = useRouter(); const connected = item.status === "Connected"; const connect = async () => { if (connected) { router.push(`/integrations/${item.id}`); return; } const response = await fetch(`/api/v1/integrations/${item.id}/connect`, { method: "POST" }); const payload = await response.json() as ApiResponse<{ authorizationUrl?: string }>; if (response.ok && payload.data?.authorizationUrl) window.location.assign(payload.data.authorizationUrl); else window.alert(payload.error?.message || "Provider configuration is required."); }; return <Card className="flex flex-wrap items-center gap-4 p-4 sm:p-5"><PlatformIcon platform={item.platform} size={42} /><div className="min-w-[210px] flex-1"><div className="flex items-center gap-2"><h2 className="text-[15px] font-extrabold text-[#111a2e]">{item.platform}</h2><StatusBadge status={connected ? "Connected" : item.status === "Needs attention" ? "Pending" : "Draft"} /></div><p className="mt-1 text-xs text-[#6f7c92]">{item.description}</p><div className="mt-3 flex flex-wrap gap-2 text-[10px] text-[#768299]"><span>◉ Campaigns</span><span>◉ Analytics</span><span>◉ Metrics</span><span>◉ Reports</span></div></div><div className="min-w-[175px] text-[11px] text-[#6f7c92]">{connected ? <><span className="block font-semibold text-[#3d4b63]">{item.account}</span><span className="mt-1 block">Last synced {item.synced || "Not synced"}</span></> : item.status === "Needs attention" ? "Provider error — review configuration" : "Provider configuration required"}</div><PrimaryButton onClick={connect} className={cn("w-24", connected && "!bg-white !bg-none !text-[#5e3cdb] !shadow-none border border-[#dcd5fb]")}>{connected ? "Manage" : "Configure"}</PrimaryButton><MoreHorizontal className="text-[#7c879a]" size={18} /></Card>; }

function SocialPage() { const resource = useApiList<SocialPost>("/api/v1/social/posts", "social-posts"); const metrics: MetricKpi[] = []; return <AppShell title="Social Media" action={<PrimaryButton><Plus size={15} />Create Post<ChevronDown size={13} /></PrimaryButton>}><PageHeading title="Social Media" description="Manage and grow your brand across all social platforms." /><div className="grid gap-3 md:grid-cols-2 xl:grid-cols-5">{metrics.map((metric) => <MetricCard key={metric.label} metric={metric} />)}</div><div className="mt-4 grid gap-4 xl:grid-cols-[minmax(0,2fr)_minmax(300px,.8fr)_minmax(300px,.9fr)]"><Card><SectionCardTitle title="Performance Overview" /><div className="mt-4"><TrendChart data={chartSeries} /></div></Card><Card><SectionCardTitle title="Audience Growth" /><div className="mt-6 text-center text-xs text-[#7d899e]">Audience metrics will appear after a social account is connected.</div><AudienceBars /></Card><Card><SectionCardTitle title="Engagement Rate by Platform" /><div className="mt-6 text-center text-xs text-[#7d899e]">No social metrics available.</div></Card></div><div className="mt-4 grid gap-4 xl:grid-cols-[minmax(0,1.4fr)_minmax(300px,.8fr)_minmax(300px,.85fr)]"><PostsCard data={resource.items} /><UpcomingPosts /><MiniCalendar /></div><Card className="mt-4"><SectionCardTitle title="Connected Accounts" action={<SecondaryButton><Settings2 size={14} />Manage Accounts</SecondaryButton>} /><div className="mt-4 text-xs text-[#7d899e]">Connect a provider to manage social accounts.</div></Card></AppShell>; }
function PostsCard({ data = posts }: { data?: SocialPost[] }) { return <Card flush><div className="flex items-center justify-between border-b border-[#edf0f4] p-4"><h2 className="text-[14px] font-extrabold">Top Performing Posts</h2><LinkButton>View all posts</LinkButton></div><div className="divide-y divide-[#edf0f4]">{data.slice(0, 5).map((post) => <div className="flex items-center gap-2.5 p-3" key={post.id}><Image src={post.image || "/media/shoes.svg"} alt="" width={48} height={36} className="h-9 w-12 rounded-md object-cover" /><PlatformIcon platform={post.platform} size={20} /><div className="min-w-0 flex-1"><div className="truncate text-xs font-bold">{post.title}</div><div className="mt-1 text-[10px] text-[#8490a4]">{post.date}</div></div><div className="text-right"><div className="text-xs font-bold text-[#26344c]">{post.engagement}</div><div className="mt-1 text-[10px] font-bold text-[#159a65]">{post.status}</div></div></div>)}</div>{!data.length && <div className="p-8 text-center text-xs text-[#7d899e]">No posts are available yet.</div>}</Card>; }
function UpcomingPosts() { return <Card><SectionCardTitle title="Upcoming Posts" action={<LinkButton>View Calendar</LinkButton>} /><div className="mt-3 space-y-3">{posts.slice(0, 4).map((post, index) => <div className="flex items-center gap-2" key={post.id}><Image src={post.image || "/media/shoes.svg"} alt="" width={44} height={36} className="h-9 w-11 rounded-md object-cover" /><PlatformIcon platform={post.platform} size={18} /><div className="min-w-0 flex-1"><div className="truncate text-xs font-bold">{["Summer Sale Announcement", "Weekly Marketing Tips", "Case Study: 200% Growth", "Quick Tip Sunday"][index]}</div><div className="mt-1 text-[10px] text-[#8490a4]">Jun {1 + index}, 2024 · 11:00 AM</div></div><StatusBadge status={index === 3 ? "Draft" : "Scheduled"} /></div>)}</div><LinkButton>View all scheduled posts</LinkButton></Card>; }
function MiniCalendar() { return <Card><div className="flex items-center justify-between"><h2 className="text-[14px] font-extrabold">Content Calendar</h2><div className="flex gap-2 text-[#8290a4]"><ChevronLeft size={16} /><ChevronRight size={16} /></div></div><div className="mt-4 text-center text-xs font-bold">May 2024</div><div className="mt-3 grid grid-cols-7 gap-y-3 text-center text-[10px] text-[#65738a]">{["Sun", "Mon", "Tue", "Wed", "Thu", "Fri", "Sat", ...Array.from({ length: 31 }, (_, index) => String(index + 1))].map((item, index) => <span key={`${item}-${index}`} className={cn(index > 6 && index === 37 && "grid h-6 w-6 place-items-center justify-self-center rounded-full bg-[#6940e8] font-bold text-white")}>{item}</span>)}</div><div className="mt-4 flex flex-wrap gap-3 text-[10px] text-[#718099]"><span><i className="mr-1 inline-block h-2 w-2 rounded-full bg-[#6940e8]" />Scheduled</span><span><i className="mr-1 inline-block h-2 w-2 rounded-full bg-[#2684e9]" />Published</span><span><i className="mr-1 inline-block h-2 w-2 rounded-full bg-[#aab3c1]" />Draft</span></div></Card>; }

function ContentStudioPage() { const [tab, setTab] = useState("Overview"); const metrics: MetricKpi[] = [{ label: "Total Content", value: "158", change: "12.4%", trend: "up", icon: "chart", tone: "purple" }, { label: "Published", value: "112", change: "15.6%", trend: "up", icon: "conversions", tone: "green" }, { label: "Scheduled", value: "28", change: "8.3%", trend: "up", icon: "calendar", tone: "orange" }, { label: "Drafts", value: "18", change: "5.2%", trend: "down", icon: "chart", tone: "blue" }, { label: "Engagement", value: "24.5K", change: "18.7%", trend: "up", icon: "conversions", tone: "pink" }]; return <AppShell title="Content Studio" action={<PrimaryButton><Plus size={15} />Create Content<ChevronDown size={13} /></PrimaryButton>}><PageHeading title="Content Studio" description="Plan, create, and manage your content across all platforms." /><Tabs items={["Overview", "Content Calendar", "Content Library", "Templates", "Media Library", "Hashtags", "Settings"]} active={tab} onChange={setTab} /><div className="mt-4 grid gap-3 md:grid-cols-2 xl:grid-cols-5">{metrics.map((metric) => <MetricCard key={metric.label} metric={metric} />)}</div>{tab === "Content Calendar" ? <ContentCalendar /> : <><div className="mt-4 grid gap-4 xl:grid-cols-[minmax(0,.9fr)_minmax(0,1.3fr)_minmax(300px,.8fr)]"><TemplatesCard /><DraftsCard /><AICreatorCard /></div><div className="mt-4 grid gap-3 md:grid-cols-2 xl:grid-cols-6">{["AI Writer", "Paraphraser", "Summarizer", "Hashtag Generator", "Tone Detector", "Grammar Checker"].map((tool) => <Card className="p-3" key={tool}><Sparkles size={17} className="text-[#6940e8]" /><div className="mt-3 text-xs font-bold">{tool}</div><p className="mt-1 text-[10px] leading-4 text-[#7e899d]">Create high-quality content with AI.</p><SecondaryButton className="mt-3 w-full text-[10px]">Use Tool</SecondaryButton></Card>)}</div></>}</AppShell>; }
function TemplatesCard() { return <Card><SectionCardTitle title="Popular Templates" action={<LinkButton>View all templates</LinkButton>} /><div className="mt-4 space-y-3">{[["Blog Post", "Write SEO-friendly blog posts in minutes."], ["Social Media Post", "Create engaging posts for any platform."], ["Product Description", "Write compelling product descriptions."], ["Email Campaign", "Create high-converting email content."], ["Ad Copy", "Generate persuasive ad copy that converts."]].map(([title, description], index) => <div className="flex gap-3" key={title}><span className={cn("grid h-9 w-9 place-items-center rounded-lg", index % 2 ? "bg-[#eaf3ff] text-[#2684e9]" : "bg-[#f0eaff] text-[#6940e8]")}><FileBarChart size={17} /></span><div><div className="text-xs font-bold">{title}</div><div className="mt-1 text-[10px] text-[#7d899d]">{description}</div></div></div>)}</div></Card>; }
function DraftsCard() { return <Card flush><div className="flex items-center justify-between border-b border-[#edf0f4] p-4"><SectionCardTitle title="Recent Drafts" action={<LinkButton>View all drafts</LinkButton>} /></div><div className="divide-y divide-[#edf0f4]">{posts.slice(0, 4).map((post) => <div className="flex items-center gap-3 p-3" key={post.id}><Image src={post.image || "/media/shoes.svg"} alt="" width={48} height={40} className="h-10 w-12 rounded-md object-cover" /><div className="min-w-0 flex-1"><div className="truncate text-xs font-bold">{post.title}</div><div className="mt-1 text-[10px] text-[#8390a4]">Instagram Post · May 31, 2024</div></div><StatusBadge status="Scheduled" /><Edit3 size={14} className="text-[#77849b]" /></div>)}</div></Card>; }
function AICreatorCard() { return <Card className="bg-[#fbfaff]"><div className="flex items-center gap-2"><Sparkles size={17} className="text-[#6940e8]" /><h2 className="text-[14px] font-extrabold">AI Content Creator</h2><span className="rounded-full bg-[#ede8ff] px-2 py-0.5 text-[9px] font-bold text-[#6940e8]">New</span></div><p className="mt-4 text-[11px] font-semibold text-[#65738b]">What would you like to create today?</p><input className="mt-2 h-9 w-full rounded-lg border border-[#e0e3ec] px-3 text-xs outline-none" placeholder="e.g., Write a post about summer sale" /><div className="mt-4 grid grid-cols-2 gap-2">{["Social Post", "Blog Idea", "Ad Copy", "Email", "Product Desc.", "Video Script"].map((item) => <button className="rounded-lg border border-[#e4e6ee] bg-white px-2 py-2 text-[10px] font-semibold text-[#4f5c73]" key={item}>{item}</button>)}</div><PrimaryButton className="mt-4 w-full"><Sparkles size={14} />Generate Content</PrimaryButton></Card>; }
function ContentCalendar() { return <div className="mt-4 grid gap-4 xl:grid-cols-[minmax(0,1fr)_330px]"><Card flush><div className="flex items-center justify-between border-b border-[#edf0f4] p-4"><div className="flex items-center gap-2"><SecondaryButton className="h-8 px-2"><ChevronLeft size={14} /></SecondaryButton><span className="text-sm font-bold">May 2024</span><SecondaryButton className="h-8 px-2"><ChevronRight size={14} /></SecondaryButton><SecondaryButton className="h-8">Today</SecondaryButton></div><SecondaryButton className="h-8 text-[#6940e8]">Calendar</SecondaryButton></div><div className="grid grid-cols-7 border-b border-[#edf0f4] text-center text-[10px] font-bold text-[#66748b]">{["Sun", "Mon", "Tue", "Wed", "Thu", "Fri", "Sat"].map((day) => <div className="py-3" key={day}>{day}</div>)}</div><div className="grid grid-cols-7">{Array.from({ length: 35 }, (_, index) => <div className="min-h-[88px] border-b border-r border-[#f0f2f6] p-2" key={index}><div className="text-[10px] font-bold text-[#69758c]">{index < 3 ? 28 + index : index - 2}</div>{index % 5 === 0 && <div className="mt-2 rounded-md bg-[#fbeaf1] p-1.5 text-[9px] font-semibold text-[#a54b6c]"><PlatformIcon platform="Instagram" size={13} />Summer Sale</div>}{index % 7 === 0 && <div className="mt-1 rounded-md bg-[#eaf3ff] p-1.5 text-[9px] font-semibold text-[#2777c6]"><PlatformIcon platform="LinkedIn" size={13} />Industry Tips</div>}</div>)}</div></Card><Card><SectionCardTitle title="Post Details" action={<SecondaryButton className="h-8 px-2"><Edit3 size={13} /></SecondaryButton>} /><div className="mt-4 flex items-center gap-2"><PlatformIcon platform="Instagram" size={24} /><StatusBadge status="Scheduled" /></div><h3 className="mt-3 text-sm font-extrabold">Summer Sale Announcement</h3><p className="mt-2 text-[11px] text-[#7b879c]">May 31, 2024 · 10:00 AM</p><p className="mt-3 text-xs leading-5 text-[#4c5971]">Our biggest sale of the year is here! 🎉 Get up to 50% off on all premium plans.</p><Image src="/media/shoes.svg" alt="Summer sale preview" width={640} height={320} className="mt-4 h-40 w-full rounded-lg object-cover" /></Card></div>; }

function LeadsPage({ detailId }: { detailId?: string }) { const resource = useApiList<Lead>("/api/v1/leads", "leads"); if (detailId) { const lead = resource.items.find((item) => item.id === detailId); if (!lead) return <AppShell title="Leads"><Card><SectionCardTitle title={resource.loading ? "Loading lead" : "Lead not found"} description={resource.error || "This lead is not available in the current workspace."} /></Card></AppShell>; return <LeadDetail lead={lead} />; } const metrics: MetricKpi[] = []; return <AppShell title="Leads" action={<PrimaryButton><Plus size={15} />Add Lead<ChevronDown size={13} /></PrimaryButton>}><PageHeading title="Leads" description="Track, manage and convert your leads efficiently." /><div className="grid gap-3 md:grid-cols-2 xl:grid-cols-5">{metrics.map((metric) => <MetricCard key={metric.label} metric={metric} />)}</div><div className="mt-4 grid gap-4 xl:grid-cols-[minmax(0,1.65fr)_minmax(300px,.8fr)_minmax(280px,.7fr)]"><LeadPipeline /><Card><SectionCardTitle title="Leads by Source" description="Source distribution is calculated from persisted lead records." /></Card><LeadStatusCard /></div><div className="mt-4 grid gap-4 xl:grid-cols-[minmax(0,1.6fr)_minmax(300px,.7fr)]"><LeadsTable data={resource.items} /><RecentActivities /></div></AppShell>; }
function LeadPipeline() { return <Card className="overflow-x-auto"><SectionCardTitle title="Lead Pipeline" /><div className="mt-5 flex min-w-[650px] items-center gap-1">{[["New", "432", "34.6%", "#ede7ff"], ["Contacted", "298", "23.9%", "#e5f0ff"], ["Qualified", "312", "25.0%", "#e5f8ed"], ["Proposal Sent", "152", "12.2%", "#fff0d8"], ["Converted", "126", "10.1%", "#ede7ff"]].map(([label, value, percent, background], index) => <div className="flex flex-1 items-center gap-1" key={label}><div className="w-full rounded-lg p-4 text-center" style={{ background }}><div className="text-[10px] font-bold text-[#5c3cba]">{label}</div><div className="mt-2 text-xl font-extrabold">{value}</div><div className="mt-1 text-[10px] font-bold text-[#5c3cba]">{percent}</div></div>{index < 4 && <ArrowRight className="shrink-0 text-[#43a791]" size={18} />}</div>)}</div><div className="mt-4 text-xs">Overall Conversion Rate: <strong className="text-[#159a65]">10.10%</strong></div></Card>; }
function LeadStatusCard() { return <Card><SectionCardTitle title="Lead Status" /><div className="mt-4 space-y-3">{[["New", "432", "34.6%", "#6940e8"], ["Contacted", "298", "23.9%", "#2684e9"], ["Qualified", "312", "25.0%", "#35b6ad"], ["Proposal Sent", "152", "12.2%", "#f3aa25"], ["Converted", "126", "10.1%", "#6940e8"]].map(([label, count, percent, color]) => <div key={label}><div className="flex justify-between text-[10px]"><span><i className="mr-2 inline-block h-2 w-2 rounded-full" style={{ background: color }} />{label}</span><strong>{count} <span className="font-normal text-[#8590a4]">{percent}</span></strong></div><div className="mt-1 h-1.5 rounded-full bg-[#edf0f5]"><div className="h-full rounded-full" style={{ width: percent, background: color }} /></div></div>)}</div><LinkButton>View full report</LinkButton></Card>; }
function LeadsTable({ data = leads }: { data?: Lead[] }) { const router = useRouter(); return <Card flush><div className="flex items-center justify-between border-b border-[#edf0f4] p-4"><SectionCardTitle title="All Leads" /><SecondaryButton className="h-8 px-2"><Download size={13} />Export</SecondaryButton></div><div className="overflow-x-auto"><table className="w-full min-w-[780px] text-left text-[10px]"><thead><tr className="border-b border-[#edf0f4] text-[#8490a4]"><th className="px-4 py-3">Lead Name</th><th className="px-3 py-3">Company</th><th className="px-3 py-3">Source</th><th className="px-3 py-3">Status</th><th className="px-3 py-3">Score</th><th className="px-3 py-3">Owner</th><th className="px-3 py-3">Created On</th><th className="px-3 py-3">Actions</th></tr></thead><tbody>{data.map((lead) => <tr key={lead.id} className="border-b border-[#f0f2f6] last:border-0 hover:bg-[#fbfbfe]"><td className="px-4 py-3"><button onClick={() => router.push(`/leads/${lead.id}`)} className="flex items-center gap-2 font-bold"><span className="grid h-7 w-7 place-items-center rounded-full bg-[#d8d0ff] text-[9px] text-[#6040c5]">{lead.name.split(" ").map((item) => item[0]).join("")}</span>{lead.name}</button></td><td className="px-3 py-3">{lead.company}</td><td className="px-3 py-3">{lead.source}</td><td className="px-3 py-3"><StatusBadge status={lead.status} /></td><td className="px-3 py-3 font-bold text-[#159a65]">{lead.score}</td><td className="px-3 py-3">{lead.owner}</td><td className="px-3 py-3">{lead.created}</td><td className="px-3 py-3"><MoreHorizontal size={15} className="text-[#8490a4]" /></td></tr>)}</tbody></table></div>{!data.length && <div className="p-8 text-center text-xs text-[#7d899e]">No leads are available yet.</div>}</Card>; }
function RecentActivities() { return <Card><SectionCardTitle title="Recent Activities" /><div className="mt-4 space-y-4">{["James Smith was marked as Qualified", "Proposal sent to Emily Johnson", "Follow up call with Michael Brown", "Anna Scott added as a new lead"].map((item, index) => <div className="flex gap-2" key={item}><span className={cn("grid h-7 w-7 shrink-0 place-items-center rounded-full", index % 2 ? "bg-[#eaf3ff] text-[#2684e9]" : "bg-[#e5f8ee] text-[#159a65]")}><Bell size={13} /></span><div><div className="text-xs font-semibold">{item}</div><div className="mt-1 text-[10px] text-[#8490a4]">by {index % 2 ? "Priya Sharma" : "Rohan Mehta"} · {index + 2} mins ago</div></div></div>)}</div><LinkButton>View full activities</LinkButton></Card>; }
function LeadDetail({ lead }: { lead: Lead }) { return <AppShell title="Leads"><div className="mb-4 text-xs text-[#728099]">Leads <ChevronRight size={13} className="mx-1 inline" /> {lead.name}</div><PageHeading title={lead.name} description={`${lead.company} · ${lead.source}`} action={<PrimaryButton><Edit3 size={14} />Edit Lead</PrimaryButton>} /><div className="grid gap-4 lg:grid-cols-[minmax(0,1.5fr)_340px]"><Card><SectionCardTitle title="Lead Overview" /><div className="mt-5 grid grid-cols-2 gap-4 sm:grid-cols-4"><div><div className="text-[10px] text-[#8490a4]">Status</div><div className="mt-1"><StatusBadge status={lead.status} /></div></div><div><div className="text-[10px] text-[#8490a4]">Lead Score</div><div className="mt-1 text-xl font-extrabold text-[#159a65]">{lead.score}</div></div><div><div className="text-[10px] text-[#8490a4]">Owner</div><div className="mt-1 text-xs font-bold">{lead.owner}</div></div><div><div className="text-[10px] text-[#8490a4]">Revenue</div><div className="mt-1 text-xs font-bold">{money(lead.revenue)}</div></div></div><div className="mt-6 border-t border-[#edf0f4] pt-5"><RecentActivities /></div></Card><Card><SectionCardTitle title="Contact Details" /><div className="mt-4 space-y-4 text-xs">{[["Company", lead.company], ["Source", lead.source], ["Created On", lead.created]].map(([label, value]) => <div key={label}><div className="text-[10px] text-[#8490a4]">{label}</div><strong className="mt-1 block">{value}</strong></div>)}</div><SecondaryButton className="mt-6 w-full"><Plus size={14} />Add Note</SecondaryButton></Card></div></AppShell>; }

function AdManagerPage() { const metrics: MetricKpi[] = [...kpis.slice(0, 3), { label: "Cost / Conversion", value: "$6.51", change: "3.2%", trend: "down", icon: "spend", tone: "orange" }, { ...kpis[3], label: "ROAS" }, { ...kpis[4], label: "CTR" } as MetricKpi]; return <AppShell title="Ad Manager" action={<div className="flex gap-2"><PrimaryButton><Plus size={15} />Create Campaign</PrimaryButton><SecondaryButton className="hidden sm:inline-flex">Bulk Actions<ChevronDown size={13} /></SecondaryButton></div>}><PageHeading title="Ad Manager" description="Create, manage and optimize your advertising campaigns." /><div className="grid gap-3 md:grid-cols-2 xl:grid-cols-6">{metrics.map((metric) => <MetricCard key={metric.label} metric={metric} compact />)}</div><div className="mt-4 grid gap-4 xl:grid-cols-[minmax(0,1.9fr)_minmax(330px,.8fr)_minmax(300px,.7fr)]"><Card><SectionCardTitle title="Campaign Performance Trend" action={<SecondaryButton className="h-8">Daily<ChevronDown size={13} /></SecondaryButton>} /><div className="mt-4"><TrendChart data={chartSeries} showRoas /></div></Card><Card><SectionCardTitle title="Spend by Platform" /><div className="mt-4"><DonutChart data={spendChartData} total="$24,500" label="Total Spend" /></div><LinkButton>View platform report</LinkButton></Card><Card><SectionCardTitle title="Campaign Status" /><div className="mt-5"><DonutChart data={[{ label: "Active", value: 18, color: "#35b6ad" }, { label: "Paused", value: 10, color: "#2684e9" }, { label: "Completed", value: 6, color: "#f3a25f" }, { label: "Draft", value: 4, color: "#ef5a72" }]} total="38" label="Total Campaigns" /></div><LinkButton>View all campaigns</LinkButton></Card></div><div className="mt-4"><CampaignTable /></div><div className="mt-4 grid gap-4 lg:grid-cols-3"><Card><SectionCardTitle title="Performance by Device" /><div className="mt-3"><DonutChart data={[{ label: "Mobile", value: 68, color: "#6940e8" }, { label: "Desktop", value: 24, color: "#2684e9" }, { label: "Tablet", value: 8, color: "#35b6ad" }]} total="68.2%" label="Mobile" /></div></Card><Card><SectionCardTitle title="Day & Time Performance" /><div className="mt-5"><Heatmap /></div><div className="mt-3 flex justify-between text-[10px] text-[#8490a4]"><span>12 AM</span><span>6 AM</span><span>12 PM</span><span>6 PM</span><span>12 AM</span></div></Card><Card><SectionCardTitle title="Budget Utilization" /><div className="mt-4 space-y-4">{campaigns.slice(0, 4).map((campaign, index) => <div key={campaign.id}><div className="flex justify-between text-[10px]"><span>{campaign.name}</span><strong>{["90%", "94%", "108%", "68%"][index]}</strong></div><div className="mt-1 h-1.5 rounded-full bg-[#edf0f5]"><div className={cn("h-full rounded-full", index === 2 ? "bg-[#ef5a67]" : "bg-[#2bb67b]")} style={{ width: `${[90, 94, 100, 68][index]}%` }} /></div></div>)}</div><LinkButton>View budget report</LinkButton></Card></div></AppShell>; }

function BillingPage() { return <AppShell title="Billing"><PageHeading title="Billing" description="Manage your subscription, payments and billing details." /><div className="grid gap-3 md:grid-cols-2 xl:grid-cols-5">{[["Current Plan", "Growth Plan", "wallet", "purple"], ["Next Billing Date", "Jun 20, 2024", "calendar", "blue"], ["Amount Due", "$199.00", "spend", "orange"], ["Billing Cycle", "Monthly", "refresh", "green"], ["Total Paid", "$1,592.00", "card", "purple"]].map(([label, value, icon, tone]) => <Card className="p-4" key={label}><div className="flex items-start gap-3"><KpiIcon type={icon} tone={tone} /><div><div className="text-[11px] text-[#6d7990]">{label}</div><div className="mt-2 text-lg font-extrabold">{value}</div><div className="mt-1 text-[10px] text-[#8490a4]">{label === "Next Billing Date" ? "19 days remaining" : label === "Amount Due" ? "Includes taxes" : "Last 12 months"}</div></div></div></Card>)}</div><div className="mt-4 grid gap-4 xl:grid-cols-[minmax(0,1.2fr)_minmax(340px,.8fr)]"><Card><SectionCardTitle title="Subscription Plan" /><div className="mt-4 grid gap-4 lg:grid-cols-[270px_1fr]"><div className="rounded-xl bg-[#f7f2ff] p-4"><div className="flex items-center gap-2"><KpiIcon type="sparkles" tone="purple" /><div><div className="text-sm font-extrabold">Growth Plan</div><div className="text-[10px] text-[#7d899d]">Perfect for growing agencies</div></div></div><div className="mt-5 text-2xl font-extrabold">$199<span className="text-xs font-medium"> /month</span></div><div className="mt-4 space-y-2 text-[11px] text-[#506078]">{["Unlimited Campaigns", "Up to 10 Team Members", "Advanced Analytics", "AI Content Credits: 10,000/month", "Priority Support", "Custom Reporting", "All Integrations Included"].map((item) => <div key={item}><Check className="mr-2 inline text-[#20ad78]" size={13} />{item}</div>)}</div><SecondaryButton className="mt-4 w-full text-[#5e3cdb]">Change Plan</SecondaryButton></div><div><div className="flex justify-between"><h3 className="text-sm font-extrabold">Usage Overview</h3><LinkButton>View all usage</LinkButton></div><div className="mt-5 space-y-6">{[["AI Content Credits", "6,250 / 10,000", "62%", "#6940e8"], ["Team Members", "6 / 10", "60%", "#2684e9"], ["Clients", "18 / 50", "36%", "#20ad78"], ["Storage", "45.2 GB / 100 GB", "45%", "#f3a427"]].map(([label, value, percent, color]) => <div key={label}><div className="flex justify-between text-xs"><span>{label}</span><strong>{value}</strong></div><div className="mt-2 h-1.5 rounded-full bg-[#e9ecf2]"><div className="h-full rounded-full" style={{ width: percent, background: color }} /></div><div className="mt-1 text-right text-[10px] text-[#8490a4]">{percent} used</div></div>)}</div></div></div></Card><div className="space-y-4"><Card><SectionCardTitle title="Payment Methods" action={<LinkButton>Add New</LinkButton>} /><div className="mt-4 space-y-3"><div className="flex items-center justify-between rounded-lg border border-[#cfc3ff] bg-[#fbfaff] p-3"><div className="flex items-center gap-3"><span className="grid h-8 w-10 place-items-center rounded bg-[#1662a5] text-[10px] font-bold text-white">VISA</span><div><div className="text-xs font-bold">Visa ending in 4242</div><div className="mt-1 text-[10px] text-[#8490a4]">Expires 12/26</div></div></div><StatusBadge status="Active" /></div><div className="flex items-center gap-3 rounded-lg border border-[#e5e8ee] p-3"><span className="grid h-8 w-10 place-items-center rounded bg-[#222] text-[10px] font-bold text-white">MC</span><div><div className="text-xs font-bold">Mastercard ending in 8888</div><div className="mt-1 text-[10px] text-[#8490a4]">Expires 09/25</div></div></div></div></Card><Card><SectionCardTitle title="Billing Summary" /><div className="mt-4 space-y-3 text-xs"><div className="flex justify-between"><span>Plan Amount</span><strong>$199.00</strong></div><div className="flex justify-between"><span>Add-ons</span><strong>$0.00</strong></div><div className="flex justify-between"><span>Discount</span><strong className="text-[#159a65]">-$0.00</strong></div><div className="flex justify-between border-t border-[#edf0f4] pt-3"><span>Subtotal</span><strong>$199.00</strong></div><div className="flex justify-between border-t border-[#edf0f4] pt-3 text-base"><strong>Total</strong><strong>$199.00 USD</strong></div></div></Card></div></div><Card className="mt-4"><SectionCardTitle title="Invoice History" action={<LinkButton>View all invoices</LinkButton>} /><div className="mt-4 overflow-x-auto"><table className="w-full min-w-[650px] text-left text-xs"><thead className="border-b border-[#edf0f4] text-[10px] text-[#8490a4]"><tr><th className="pb-3">Invoice ID</th><th className="pb-3">Date</th><th className="pb-3">Description</th><th className="pb-3">Amount</th><th className="pb-3">Status</th><th className="pb-3">Actions</th></tr></thead><tbody>{["INV-2024-0012", "INV-2024-0011", "INV-2024-0010", "INV-2024-0009", "INV-2024-0008"].map((invoice, index) => <tr className="border-b border-[#f0f2f6] last:border-0" key={invoice}><td className="py-3 font-semibold">{invoice}</td><td className="py-3">May {20 - index * 3}, 2024</td><td className="py-3">Growth Plan - Monthly</td><td className="py-3 font-bold">$199.00</td><td className="py-3"><StatusBadge status="Paid" /></td><td className="py-3"><Download size={14} /></td></tr>)}</tbody></table></div></Card></AppShell>; }

function SettingsPage({ subsection }: { subsection?: string }) { const [saved, setSaved] = useState(false); const items = ["General", "Profile", "Security", "Notifications", "Integrations", "Billing & Subscription", "Team Management", "Roles & Permissions", "Data Management", "Preferences", "API & Webhooks", "Audit Logs"]; return <AppShell title="Settings"><PageHeading title="Settings" description="Manage your account, preferences, and system settings." /><div className="grid gap-4 xl:grid-cols-[240px_minmax(0,1fr)_300px]"><Card className="p-2"><div className="space-y-1">{items.map((item, index) => <button className={cn("flex w-full items-center gap-3 rounded-lg px-3 py-2.5 text-left", (subsection || "general") === item.toLowerCase().split(" ")[0] ? "bg-[#f1edff] text-[#5e3cdb]" : "text-[#526079] hover:bg-[#f7f8fb]")} key={item}><Settings2 size={16} /><span><span className="block text-xs font-bold">{item}</span><span className="mt-0.5 block text-[9px] opacity-70">Account settings and preferences</span></span></button>)}</div></Card><Card><div className="flex items-center justify-between"><SectionCardTitle title="General Settings" description="Manage your general account settings and preferences." /><PrimaryButton onClick={() => setSaved(true)}>{saved ? <Check size={14} /> : null}{saved ? "Saved" : "Save Changes"}</PrimaryButton></div><div className="mt-5 space-y-4">{[["Company Name", "MarketerOS Agency"], ["Time Zone", "(GMT+05:30) Asia/Kolkata"], ["Date Format", "May 31, 2024 (MMM DD, YYYY)"], ["Time Format", "12 Hour (01:30 PM)"], ["Language", "English"], ["Currency", "USD – US Dollar ($)"], ["Default Dashboard", "Overview"]].map(([label, value]) => <label className="grid items-center gap-3 border-b border-[#edf0f4] pb-4 sm:grid-cols-[1fr_260px]" key={label}><span><span className="block text-xs font-bold">{label}</span><span className="mt-1 block text-[10px] text-[#8490a4]">Choose your preferred {label.toLowerCase()}.</span></span><div className="flex h-9 items-center justify-between rounded-lg border border-[#e0e4eb] px-3 text-xs"><span>{value}</span><ChevronDown size={13} className="text-[#8490a4]" /></div></label>)}</div><div className="mt-6 rounded-lg border border-[#edebff] bg-[#faf9ff] p-3 text-xs text-[#5e3cdb]"><Sparkles className="mr-2 inline" size={15} />Don't worry, you can always update these details later from settings.</div></Card><div className="space-y-4"><Card><SectionCardTitle title="Account Overview" /><div className="mt-4 space-y-3 text-xs"><div className="flex justify-between"><span>Plan</span><strong>Growth Plan</strong></div><div className="flex justify-between"><span>Status</span><StatusBadge status="Active" /></div><div className="flex justify-between"><span>Member Since</span><strong>Jan 20, 2024</strong></div><div className="flex justify-between"><span>Next Billing Date</span><strong>Jun 20, 2024</strong></div></div><LinkButton>View Subscription Details</LinkButton></Card><Card><SectionCardTitle title="Quick Links" /><div className="mt-3 space-y-1">{["Change Password", "Download Data", "Close Account"].map((item) => <button className="flex w-full items-center justify-between border-b border-[#edf0f4] py-3 text-xs font-semibold last:border-0" key={item}>{item}<ChevronRight size={14} /></button>)}</div></Card><Card><SectionCardTitle title="Storage Usage" /><div className="mt-4 flex justify-between text-xs"><span>45.2 GB / 100 GB</span><strong>45%</strong></div><div className="mt-2 h-2 rounded-full bg-[#edf0f5]"><div className="h-full w-[45%] rounded-full bg-[#6940e8]" /></div></Card></div></div></AppShell>; }

function ReportsPage() { return <AppShell title="Reports" action={<PrimaryButton><Plus size={15} />Create Report</PrimaryButton>}><PageHeading title="Reports" description="Create, schedule and share performance reports with your team and clients." /><div className="grid gap-3 md:grid-cols-3"><MetricCard metric={{ label: "Total Reports", value: "24", change: "12.4%", trend: "up", icon: "chart", tone: "purple" }} /><MetricCard metric={{ label: "Scheduled", value: "8", change: "8.3%", trend: "up", icon: "calendar", tone: "blue" }} /><MetricCard metric={{ label: "Generated This Month", value: "16", change: "18.7%", trend: "up", icon: "chart", tone: "green" }} /></div><Card className="mt-4"><SectionCardTitle title="Recent Reports" action={<SecondaryButton><Filter size={14} />Filters</SecondaryButton>} /><div className="mt-4 overflow-x-auto"><table className="w-full min-w-[700px] text-left text-xs"><thead className="border-b border-[#edf0f4] text-[10px] text-[#8490a4]"><tr><th className="pb-3">Report Name</th><th className="pb-3">Type</th><th className="pb-3">Created On</th><th className="pb-3">Status</th><th className="pb-3">Actions</th></tr></thead><tbody>{["Monthly Marketing Performance", "Acme Corp Campaign Report", "Social Media Overview", "Lead Generation Report"].map((report, index) => <tr className="border-b border-[#f0f2f6] last:border-0" key={report}><td className="py-4 font-bold">{report}</td><td className="py-4 text-[#728099]">{index % 2 ? "Client Report" : "Performance"}</td><td className="py-4 text-[#728099]">May {28 - index}, 2024</td><td className="py-4"><StatusBadge status={index === 3 ? "Draft" : "Ready"} /></td><td className="py-4"><div className="flex gap-3 text-[#69758c]"><Download size={15} /><MoreHorizontal size={15} /></div></td></tr>)}</tbody></table></div></Card></AppShell>; }
function TeamPage() { return <AppShell title="Team" action={<PrimaryButton><Plus size={15} />Invite Member</PrimaryButton>}><PageHeading title="Team" description="Manage your team members and access permissions." /><Card><SectionCardTitle title="Team Members" action={<SecondaryButton><Filter size={14} />Filters</SecondaryButton>} /><div className="mt-4 divide-y divide-[#edf0f4]">{[["Rohan Mehta", "rohan@acme.com", "Agency Admin"], ["Priya Sharma", "priya@acme.com", "Marketing Manager"], ["Amit Verma", "amit@acme.com", "Analyst"], ["Sarah Wilson", "sarah@acme.com", "Content Manager"]].map(([name, email, title]) => <div className="flex flex-wrap items-center gap-3 py-4" key={email}><span className="grid h-9 w-9 place-items-center rounded-full bg-[#dce7ff] text-[10px] font-bold text-[#3f5f92]">{name.split(" ").map((part) => part[0]).join("")}</span><div className="min-w-[180px] flex-1"><div className="text-xs font-bold">{name}</div><div className="mt-1 text-[10px] text-[#8490a4]">{email}</div></div><div className="text-xs text-[#67748a]">{title}</div><StatusBadge status="Active" /><MoreHorizontal size={16} className="text-[#8490a4]" /></div>)}</div></Card></AppShell>; }
function ClientsPage({ detailId }: { detailId?: string }) { if (detailId) return <AppShell title="Clients"><PageHeading title="Acme Corp" description="Client details, campaigns, reports and performance." action={<PrimaryButton><Edit3 size={14} />Edit Client</PrimaryButton>} /><div className="grid gap-4 md:grid-cols-3"><MetricCard metric={{ label: "Total Spend", value: "$24,500", change: "8.4%", trend: "up", icon: "spend", tone: "purple" }} /><MetricCard metric={{ label: "Campaigns", value: "12", change: "12.6%", trend: "up", icon: "chart", tone: "blue" }} /><MetricCard metric={{ label: "ROAS", value: "4.35", change: "16.7%", trend: "up", icon: "roas", tone: "green" }} /></div><Card className="mt-4"><SectionCardTitle title="Client Campaigns" /><div className="mt-4"><CampaignTable /></div></Card></AppShell>; return <AppShell title="Clients" action={<PrimaryButton><Plus size={15} />Add Client</PrimaryButton>}><PageHeading title="Clients" description="Manage brands, stakeholders, and client performance." /><div className="grid gap-4 md:grid-cols-2 xl:grid-cols-3">{["Acme Corp", "Urbanic", "TripGo", "Lyka", "moon"].map((client, index) => <Card className="cursor-pointer transition hover:-translate-y-0.5 hover:border-[#c8bcff]" key={client}><div className="flex items-center gap-3"><span className="grid h-10 w-10 place-items-center rounded-xl bg-[#f0eaff] text-sm font-extrabold text-[#6940e8]">{client[0]}</span><div><h2 className="text-sm font-extrabold">{client}</h2><p className="mt-1 text-[10px] text-[#8490a4]">{index + 2} active campaigns</p></div></div><div className="mt-4 flex justify-between border-t border-[#edf0f4] pt-3 text-[10px]"><span className="text-[#8490a4]">Monthly Spend</span><strong>{money(5420 + index * 820)}</strong></div></Card>)}</div></AppShell>; }
function AIContentPage() { return <AppShell title="AI Content Creator"><PageHeading title="AI Content Creator" description="Create on-brand marketing content in seconds." /><div className="grid gap-4 lg:grid-cols-[minmax(0,1.3fr)_340px]"><Card><SectionCardTitle title="What would you like to create?" /><textarea className="mt-4 min-h-[170px] w-full rounded-lg border border-[#e0e4eb] p-4 text-sm outline-none focus:border-[#9e8af5]" placeholder="Describe your content idea..." /><div className="mt-4 grid gap-3 sm:grid-cols-3">{["Social Post", "Blog Post", "Ad Copy", "Email Campaign", "Product Description", "Video Script"].map((item) => <button className="rounded-lg border border-[#e2e5ec] p-3 text-left text-xs font-bold hover:border-[#bcaefb]" key={item}><Sparkles size={16} className="mb-2 text-[#6940e8]" />{item}</button>)}</div><PrimaryButton className="mt-5 w-full"><Sparkles size={15} />Generate Content</PrimaryButton></Card><Card><SectionCardTitle title="Brand Voice" /><div className="mt-4 space-y-3 text-xs">{["Professional", "Friendly", "Confident", "Concise"].map((item) => <label className="flex items-center gap-2" key={item}><input type="checkbox" defaultChecked className="accent-[#6940e8]" />{item}</label>)}</div><div className="mt-6 rounded-lg bg-[#fbf9ff] p-4 text-xs text-[#65728a]"><Sparkles className="mr-2 inline text-[#6940e8]" size={15} />AI suggestions use your workspace goals, audience, and brand context.</div></Card></div></AppShell>; }
function AIInsightsPage() { const resource = useApiList<typeof insights[number]>("/api/v1/ai/insights", "ai-insights"); return <AppShell title="AI Insights"><PageHeading title="AI Insights" description="Actionable recommendations generated from your marketing data." action={<SecondaryButton><Filter size={14} />Filters</SecondaryButton>} />{resource.error && <Card className="mb-4 border-[#f2c4c8] text-xs text-[#b72e38]">{resource.error}</Card>}<div className="grid gap-4 md:grid-cols-2">{resource.items.map((insight) => <Card key={insight.id}><div className="flex gap-3"><KpiIcon type="sparkles" tone={insight.tone} /><div><div className="flex items-center gap-2"><StatusBadge status="Ready" /><span className="text-[10px] text-[#8792a6]">{insight.category}</span></div><h2 className="mt-2 text-sm font-extrabold">{insight.title}</h2><p className="mt-2 text-xs leading-5 text-[#6f7c92]">{insight.description}</p><div className="mt-4 flex items-center justify-between"><span className="text-[10px] font-bold text-[#159a65]">{insight.impact}</span><SecondaryButton className="h-8">Review</SecondaryButton></div></div></div></Card>)}{!resource.loading && !resource.items.length && <Card className="p-8 text-center text-xs text-[#7d899e] md:col-span-2">No AI insights have been generated for this workspace.</Card>}</div></AppShell>; }
function AutomationPage() { const [enabled, setEnabled] = useState(true); return <AppShell title="Automation" action={<PrimaryButton><Plus size={15} />Create Automation</PrimaryButton>}><PageHeading title="Automation" description="Turn repeatable decisions into reliable workflows." /><Card className="border-[#ded7ff] bg-[#fbf9ff]"><div className="flex items-start gap-3"><span className="grid h-9 w-9 place-items-center rounded-lg bg-[#6940e8] text-white"><Zap size={17} /></span><div><h2 className="text-sm font-extrabold">Automations run in the background</h2><p className="mt-1 text-xs text-[#728099]">Connect triggers, conditions, and actions to keep your team focused on high-value work.</p></div></div></Card><div className="mt-4 space-y-3">{[["Alert when ROAS falls below target", "ROAS below 3.0x", "Notify manager"], ["Assign high-scoring leads", "Lead score above 85", "Assign to sales team"], ["Flag performance drops", "Conversions down 20%", "Create AI insight"]].map(([name, trigger, action]) => <Card className="flex flex-wrap items-center justify-between gap-4" key={name}><div className="flex items-center gap-3"><span className="grid h-9 w-9 place-items-center rounded-lg bg-[#e6f8ee] text-[#159a65]"><Zap size={16} /></span><div><div className="text-sm font-bold">{name}</div><div className="mt-1 text-xs text-[#728099]">{trigger} <ArrowRight className="mx-1 inline" size={12} /> {action}</div></div></div><div className="flex items-center gap-3"><button onClick={() => setEnabled(!enabled)} className={cn("relative h-6 w-11 rounded-full", enabled ? "bg-[#6940e8]" : "bg-[#dfe3eb]")}><span className={cn("absolute top-1 h-4 w-4 rounded-full bg-white transition", enabled ? "left-6" : "left-1")} /></button><MoreHorizontal size={16} /></div></Card>)}</div></AppShell>; }

function AuthPage({ mode }: { mode: "login" | "signup" | "forgot-password" | "reset-password" | "verify-email" }) { const router = useRouter(); const [submitted, setSubmitted] = useState(false); const signup = mode === "signup"; const title = mode === "login" ? "Welcome back" : mode === "signup" ? "Create your account" : mode === "verify-email" ? "Check your inbox" : "Reset your password"; return <div className="flex min-h-screen bg-[#faf9ff]"><div className="hidden w-[42%] overflow-hidden bg-gradient-to-br from-[#07152f] via-[#111a43] to-[#321a73] p-10 lg:block"><ProductLogo /><div className="mt-24 max-w-[500px]"><h2 className="text-[40px] font-extrabold leading-[1.08] tracking-[-.06em] text-white">The all-in-one platform<br />to <span className="text-[#9677ff]">grow your brand</span></h2><p className="mt-5 text-base leading-7 text-[#c0c7d7]">Connect your marketing channels, analyze performance, get AI-powered insights, and scale your growth.</p><div className="mt-10 space-y-6">{["Unified Analytics", "Multi-Platform Management", "AI-Powered Insights", "Automated Reports"].map((heading, index) => <div className="flex items-center gap-4" key={heading}><span className={cn("grid h-12 w-12 place-items-center rounded-xl text-white", ["bg-[#6940e8]", "bg-[#2585e6]", "bg-[#1ca96e]", "bg-[#f19a25]"][index])}><Sparkles size={22} /></span><div><div className="text-sm font-extrabold text-white">{heading}</div><div className="mt-1 text-xs text-[#c0c7d7]">Built to help your team make better marketing decisions.</div></div></div>)}</div></div><div className="absolute bottom-8 left-10 rounded-xl border border-white/10 bg-white/[.07] px-6 py-4 text-sm font-semibold text-white">Trusted by 500+ marketing teams</div></div><div className="flex flex-1 flex-col p-5 sm:p-10"><div className="flex justify-end text-xs text-[#65728a]">{signup ? "Already have an account?" : "Don't have an account?"} <button onClick={() => router.push(signup ? "/auth/login" : "/auth/signup")} className="ml-1 font-bold text-[#5e3cdb]">{signup ? "Sign in" : "Create one"}</button></div><div className="mx-auto mt-10 w-full max-w-[720px] rounded-2xl border border-[#e7e9f0] bg-white p-6 shadow-[0_12px_35px_rgba(22,31,54,.06)] sm:mt-16 sm:p-9"><h1 className="text-[29px] font-extrabold tracking-[-.05em] text-[#111a2e]">{title}</h1><p className="mt-2 text-sm text-[#6d7890]">{signup ? "Start your 14-day free trial. No credit card required." : "Enter your details to continue to your workspace."}</p>{submitted ? <div className="mt-8 rounded-xl border border-[#c8ecd9] bg-[#effbf5] p-5 text-sm text-[#148b5a]"><Check size={20} /><div className="mt-2 font-bold">You're all set for this demo.</div><PrimaryButton onClick={() => router.push("/overview")} className="mt-4">Open Workspace<ArrowRight size={14} /></PrimaryButton></div> : <><div className="mt-7 grid gap-3 sm:grid-cols-3">{["Google", "Meta", "Microsoft"].map((label) => <SecondaryButton key={label} className="h-12 justify-start"><span className="font-bold text-[#4285f4]">{label[0]}</span>Sign up with {label}</SecondaryButton>)}</div><div className="my-6 flex items-center gap-3 text-xs text-[#8590a4]"><span className="h-px flex-1 bg-[#e8eaf0]" />Or sign up with email<span className="h-px flex-1 bg-[#e8eaf0]" /></div><div className="grid gap-4 sm:grid-cols-2">{signup && <Field label="Full Name" placeholder="Enter your full name" className="sm:col-span-2" />}{!signup && <Field label="Email address" value="alex@acme.com" className="sm:col-span-2" />}{signup && <Field label="Work Email" placeholder="you@company.com" />}{(signup || mode === "login" || mode === "reset-password") && <Field label="Password" placeholder="Create a strong password" type="password" />}{signup && <Field label="Company Name" placeholder="Enter your company name" className="sm:col-span-2" />}{signup && <><Field label="Your Role" placeholder="Select your role" /><Field label="Company Size" placeholder="Select company size" /></>}</div>{signup && <label className="mt-4 flex items-center gap-2 text-xs text-[#6d7890]"><input type="checkbox" className="accent-[#6940e8]" />I agree to the <span className="font-bold text-[#5e3cdb]">Terms of Service</span> and <span className="font-bold text-[#5e3cdb]">Privacy Policy</span></label>}<PrimaryButton onClick={() => setSubmitted(true)} className="mt-6 h-11 w-full text-sm">{signup ? "Create Account" : mode === "verify-email" ? "Resend Email" : "Continue"}</PrimaryButton><div className="mt-5 flex items-center gap-2 text-xs text-[#718098]"><ShieldCheck size={16} />Your data is secure and protected. We never share your information.</div></>}</div></div></div>; }

function OnboardingPage({ step }: { step: string }) { const router = useRouter(); const steps = [["brand", "Create Brand", "Tell us about your brand"], ["platforms", "Connect Platforms", "Add your marketing accounts"], ["goals", "Marketing Goals", "Set your objectives"], ["audience", "Audience & Industry", "Define your target audience"], ["complete", "Complete", "You're all set to go!"]]; const current = Math.max(0, steps.findIndex((item) => item[0] === step)); return <div className="flex min-h-screen bg-[#fafbfe]"><aside className="hidden w-[212px] flex-col bg-[#08152e] p-4 lg:flex"><ProductLogo /><div className="mt-8 space-y-2">{steps.map(([id, title, description], index) => <div className={cn("relative rounded-xl p-3", current === index ? "bg-[#5f3cd4]" : "bg-transparent")} key={id}><div className="flex items-start gap-3"><span className={cn("grid h-8 w-8 shrink-0 place-items-center rounded-full border text-xs font-bold", current >= index ? "border-[#987bff] bg-[#6940e8] text-white" : "border-[#73809a] text-white")}>{current > index ? <Check size={14} /> : index + 1}</span><div><div className="text-xs font-bold text-white">{title}</div><div className="mt-1 text-[10px] text-[#c5cbe0]">{description}</div></div></div>{index < 4 && <span className="absolute left-[27px] top-[43px] h-6 w-px bg-[#51607f]" />}</div>)}</div><div className="mt-auto rounded-xl border border-white/10 bg-white/[.06] p-5 text-center"><Rocket className="mx-auto text-[#987bff]" size={42} /><div className="mt-3 text-sm font-bold text-white">Almost there!</div><p className="mt-2 text-[10px] leading-5 text-[#b4bed2]">This quick setup helps us personalize your dashboard and AI insights.</p></div></aside><div className="min-w-0 flex-1"><header className="flex h-[72px] items-center justify-between border-b border-[#e7eaf0] bg-white px-5 sm:px-8"><div><div className="text-sm font-extrabold">{steps[current][1]}</div><div className="mt-1 text-[11px] text-[#77849b]">Step {current + 1} of 5</div></div><div className="hidden items-center gap-3 sm:flex"><span className="text-xs text-[#67738b]"><CircleHelp size={15} className="mr-1 inline" />Need help?</span><span className="grid h-8 w-8 place-items-center rounded-full bg-[#dce7ff] text-[10px] font-bold text-[#3f5e91]">RM</span><span className="text-xs font-bold">Rohan Mehta</span></div></header><main className="mx-auto max-w-[1200px] px-5 py-8 sm:px-10"><PageHeading title={steps[current][1]} description={steps[current][2]} />{step === "complete" ? <Card className="mx-auto max-w-[650px] p-10 text-center"><span className="mx-auto grid h-16 w-16 place-items-center rounded-full bg-[#e5f8ee] text-[#159a65]"><Check size={30} /></span><h2 className="mt-5 text-2xl font-extrabold">Your workspace is ready</h2><p className="mx-auto mt-2 max-w-md text-sm text-[#718098]">We've set up your Acme Corp workspace. Start by creating a campaign or reviewing your AI insights.</p><PrimaryButton onClick={() => router.push("/overview")} className="mt-6">Go to Dashboard<ArrowRight size={14} /></PrimaryButton></Card> : <div className="grid gap-4 xl:grid-cols-[minmax(0,1fr)_280px]"><Card>{step === "brand" && <div className="grid gap-5 sm:grid-cols-2"><Field label="Brand / Business Name" value="Acme Corp" /><Field label="Website (Optional)" value="https://acmecorp.com" /><Field label="Industry" value="E-commerce" /><Field label="Business Type" value="B2C" /><label className="sm:col-span-2"><span className="mb-1.5 block text-xs font-bold">Description (Optional)</span><textarea defaultValue="We sell premium lifestyle products online." className="h-24 w-full rounded-lg border border-[#dfe3eb] p-3 text-xs outline-none" /></label><Field label="Country" value="🇮🇳 India" /><Field label="Currency" value="USD - US Dollar ($)" /><Field label="Time Zone" value="(GMT+05:30) Asia/Kolkata" /><Field label="Monthly Marketing Budget" value="$10,000" /></div>}{step === "platforms" && <div className="space-y-3">{integrations.map((item) => <IntegrationRow item={item} key={item.id} />)}</div>}{step === "goals" && <div className="grid gap-3 sm:grid-cols-2">{["Increase sales", "Generate more leads", "Improve ROAS", "Grow awareness", "Increase engagement", "Reduce acquisition cost"].map((goal, index) => <label className="flex items-center gap-3 rounded-lg border border-[#e2e5ec] p-4 text-xs font-bold" key={goal}><input type="checkbox" defaultChecked={index < 3} className="accent-[#6940e8]" />{goal}</label>)}</div>}{step === "audience" && <div className="grid gap-5 sm:grid-cols-2"><Field label="Primary Audience" value="Marketing leaders at growing companies" /><Field label="Age Range" value="25–54" /><Field label="Geography" value="India, United States, UK" /><Field label="Languages" value="English" /><Field label="Interests" value="Growth, SaaS, analytics" /><Field label="Customer Type" value="B2B decision maker" /></div>}<div className="mt-6 flex justify-between border-t border-[#edf0f4] pt-5"><SecondaryButton onClick={() => router.push(current === 0 ? "/auth/signup" : `/onboarding/${steps[current - 1][0]}`)}><ChevronLeft size={14} />Back</SecondaryButton><PrimaryButton onClick={() => router.push(`/onboarding/${steps[Math.min(current + 1, 4)][0]}`)}>Next: {steps[Math.min(current + 1, 4)][1]}<ArrowRight size={14} /></PrimaryButton></div></Card><Card><SectionCardTitle title="Why we need this?" /><div className="mt-4 space-y-4 text-xs"><div><Check className="mr-2 inline text-[#20ad78]" size={15} /><strong>Personalized dashboard</strong><p className="ml-6 mt-1 leading-5 text-[#7b879c]">Get data and insights tailored to your business.</p></div><div><Check className="mr-2 inline text-[#20ad78]" size={15} /><strong>Better AI recommendations</strong><p className="ml-6 mt-1 leading-5 text-[#7b879c]">Our AI understands your industry and goals.</p></div><div><Check className="mr-2 inline text-[#20ad78]" size={15} /><strong>Smarter reporting</strong><p className="ml-6 mt-1 leading-5 text-[#7b879c]">We'll show you the metrics that matter most.</p></div></div></Card></div>}</main></div></div>; }

function CampaignDetailPage({ campaignId }: { campaignId?: string }) { const router = useRouter(); const campaign = campaigns.find((item) => item.id === campaignId) || campaigns[0]; const [tab, setTab] = useState("Overview"); return <AppShell title="Campaigns" action={<PrimaryButton onClick={() => router.push("/campaigns/create")}><Plus size={15} />Create Similar</PrimaryButton>}><div className="mb-4 flex items-center gap-2 text-xs text-[#718098]"><button onClick={() => router.push("/campaigns")} className="hover:text-[#5e3cdb]">Campaigns</button><ChevronRight size={13} /><span>{campaign.name}</span></div><div className="flex flex-wrap items-start justify-between gap-3"><div><div className="flex items-center gap-3"><h1 className="text-[26px] font-extrabold tracking-[-.05em] text-[#10192d]">{campaign.name}</h1><StatusBadge status={campaign.status} /></div><p className="mt-1 text-xs text-[#7b879c]">{campaign.platform} {campaign.objective} Campaign · Created on May 1, 2024</p></div><div className="flex gap-2"><SecondaryButton><Edit3 size={14} />Edit Campaign</SecondaryButton><SecondaryButton><MoreHorizontal size={14} />More</SecondaryButton></div></div><Card flush className="mt-4"><div className="flex items-center gap-3 overflow-x-auto px-4 pt-4"><Tabs items={["Overview", "Ad Groups", "Ads", "Keywords", "Audiences", "Placements", "Settings", "Change History"]} active={tab} onChange={setTab} /></div></Card>{tab !== "Overview" ? <EntityList title={tab} /> : <><div className="mt-4 grid gap-3 sm:grid-cols-2 xl:grid-cols-6">{[["Spend", "$5,420", "spend", "purple"], ["Clicks", "32,145", "clicks", "blue"], ["Conversions", "832", "conversions", "green"], ["Cost / Conv.", "$6.51", "spend", "orange"], ["ROAS", "3.82", "roas", "blue"], ["CTR", "2.45%", "ctr", "purple"]].map(([label, value, icon, tone]) => <MetricCard key={label} metric={{ label, value, change: label === "Cost / Conv." ? "3.2%" : "8.4%", trend: label === "Cost / Conv." ? "down" : "up", icon, tone } as MetricKpi} />)}</div><div className="mt-4 grid gap-4 xl:grid-cols-[minmax(0,1.5fr)_minmax(350px,1fr)]"><Card><SectionCardTitle title="Performance Over Time" action={<SecondaryButton className="h-8">Daily<ChevronDown size={13} /></SecondaryButton>} /><div className="mt-3"><TrendChart data={chartSeries} /></div></Card><CampaignStatusCard /></div><div className="mt-4 grid gap-4 lg:grid-cols-3"><DataTableCard title="Top Performing Ad Groups" /><Card><SectionCardTitle title="Device Breakdown" /><div className="mt-3"><DonutChart data={[{ label: "Mobile", value: 18745, color: "#3979eb" }, { label: "Desktop", value: 10245, color: "#35b6ad" }, { label: "Tablet", value: 3155, color: "#f3b321" }]} total="32,145" label="Clicks" /></div><LinkButton>View device performance</LinkButton></Card><DataTableCard title="Top Keywords" /></div><InsightsCard /></>}</AppShell>; }
function CampaignStatusCard() { return <Card><SectionCardTitle title="Campaign Status" /><div className="mt-4 grid grid-cols-2 gap-x-5 gap-y-4 text-xs"><div><span className="block text-[10px] text-[#7f8ca1]">Status</span><span className="mt-1 block"><StatusBadge status="Active" /></span></div><div><span className="block text-[10px] text-[#7f8ca1]">Start Date</span><strong className="mt-1 block">May 1, 2024</strong></div><div><span className="block text-[10px] text-[#7f8ca1]">End Date</span><strong className="mt-1 block">May 31, 2024</strong></div><div><span className="block text-[10px] text-[#7f8ca1]">Budget</span><strong className="mt-1 block">$5,000 / day</strong></div><div><span className="block text-[10px] text-[#7f8ca1]">Campaign Type</span><strong className="mt-1 block">Search</strong></div><div><span className="block text-[10px] text-[#7f8ca1]">Platform</span><strong className="mt-1 flex items-center gap-1"><PlatformIcon platform="Google Ads" size={17} />Google Ads</strong></div></div><SecondaryButton className="mt-5 w-full"><Settings2 size={14} />View Campaign Settings</SecondaryButton></Card>; }
function EntityList({ title }: { title: string }) { return <Card className="mt-4"><div className="flex items-center justify-between"><SectionCardTitle title={title} description={`Manage ${title.toLowerCase()} for Summer Sale Campaign.`} /><PrimaryButton><Plus size={14} />Add {title.slice(0, -1)}</PrimaryButton></div><div className="mt-4 divide-y divide-[#edf0f4]">{["Brand Keywords", "Summer Sale", "Product Category", "Competitor Terms", "Remarketing Visitors"].map((row, index) => <div key={row} className="flex items-center justify-between py-3"><div className="flex items-center gap-3"><span className="grid h-8 w-8 place-items-center rounded-lg bg-[#f0eaff] text-xs font-bold text-[#6940e8]">0{index + 1}</span><div><div className="text-xs font-bold">{row}</div><div className="mt-1 text-[10px] text-[#8792a6]">Updated May {index + 3}, 2024</div></div></div><div className="flex items-center gap-3"><StatusBadge status={index === 3 ? "Paused" : "Active"} /><MoreHorizontal size={16} className="text-[#8490a5]" /></div></div>)}</div></Card>; }
function CampaignStatusBadge() { return <StatusBadge status="Active" />; }

function CampaignWizard() { const router = useRouter(); const [step, setStep] = useState(1); const steps = ["Campaign Setup", "Ad Set & Audience", "Ad Creative", "Budget & Schedule", "Review & Launch"]; return <AppShell title="Create Campaign" action={<div className="flex gap-2"><SecondaryButton>Save as Draft</SecondaryButton><PrimaryButton><Rocket size={14} />Launch Campaign</PrimaryButton></div>}><div className="mb-4 flex items-center gap-2 text-xs text-[#728099]">Campaigns <ChevronRight size={13} /> Create Campaign</div><PageHeading title="Create New Campaign" description="Build a new campaign in just a few simple steps." /><Card flush><div className="grid grid-cols-5 border-b border-[#edf0f4] p-4 sm:p-5">{steps.map((label, index) => <button className={cn("flex items-center gap-2 text-left", index + 1 === step ? "text-[#6940e8]" : "text-[#6f7c92]")} onClick={() => setStep(index + 1)} key={label}><span className={cn("grid h-8 w-8 place-items-center rounded-full border text-xs font-bold", index + 1 === step ? "border-[#6940e8] bg-[#6940e8] text-white" : index + 1 < step ? "border-[#20ad78] bg-[#e5f8ee] text-[#159a65]" : "border-[#dfe3ea]")}>{index + 1 < step ? <Check size={14} /> : index + 1}</span><span className="hidden text-xs font-bold sm:block">{label}</span></button>)}</div><div className="grid gap-5 p-4 sm:p-6 xl:grid-cols-[minmax(0,1fr)_330px]"><div><div className="text-sm font-extrabold">{steps[step - 1]}</div><p className="mt-1 text-xs text-[#728099]">Define the details of your campaign.</p>{step === 1 && <div className="mt-5 grid gap-5 sm:grid-cols-2"><Field label="Campaign Name *" value="Summer Sale Campaign" /><Field label="Campaign Objective *" value="Sales" /><Field label="Marketing Platform *" value="Google Ads" /><Field label="Campaign Type *" value="Search" /><label className="sm:col-span-2"><span className="mb-1.5 block text-xs font-bold">Campaign Description (Optional)</span><textarea defaultValue="Promote our summer sale and increase online sales for our top products." className="h-24 w-full rounded-lg border border-[#dfe3eb] p-3 text-xs" /></label><Field label="Conversion Tracking" value="Purchase" /><Field label="Campaign Tags (Optional)" value="summer sale, india, ecommerce" /></div>}{step === 2 && <div className="mt-5 grid gap-5 sm:grid-cols-2"><Field label="Locations" value="India" /><Field label="Languages" value="English" /><Field label="Age Range" value="25–54" /><Field label="Audience" value="High intent shoppers" /></div>}{step === 3 && <div className="mt-5 grid gap-5 sm:grid-cols-2"><Field label="Primary Text" value="Summer sale is here. Save up to 50%." /><Field label="Headline" value="The Summer Sale" /><Field label="Call to Action" value="Shop Now" /><Field label="Landing Page" value="https://acmecorp.com/sale" /></div>}{step === 4 && <div className="mt-5 grid gap-5 sm:grid-cols-2"><Field label="Daily Budget" value="$5,000" /><Field label="Total Budget" value="$25,000" /><Field label="Start Date" value="May 1, 2024" /><Field label="End Date" value="May 31, 2024" /><Field label="Bidding Strategy" value="Maximize Conversions" /><Field label="Target ROAS" value="4.0" /></div>}{step === 5 && <div className="mt-5 space-y-3">{[["Campaign Name", "Summer Sale Campaign"], ["Objective", "Sales"], ["Platform", "Google Ads"], ["Type", "Search"], ["Budget", "$5,000 / day"]].map(([label, value]) => <div className="flex items-center justify-between rounded-lg bg-[#f8f9fc] p-4 text-xs" key={label}><span className="text-[#7d899e]">{label}</span><strong>{value}</strong></div>)}<div className="rounded-lg bg-[#effbf5] p-4 text-xs text-[#159a65]"><Check className="mr-2 inline" size={14} />Everything looks ready. You can still save this as a draft.</div></div>}<div className="mt-6 flex justify-between border-t border-[#edf0f4] pt-5"><SecondaryButton onClick={() => step === 1 ? router.push("/campaigns") : setStep(step - 1)}>{step === 1 ? "Cancel" : <><ChevronLeft size={14} />Back</>}</SecondaryButton><div className="flex gap-2"><SecondaryButton>Save draft</SecondaryButton><PrimaryButton onClick={() => step === 5 ? router.push("/campaigns") : setStep(step + 1)}>{step === 5 ? "Launch Campaign" : "Next"}<ArrowRight size={14} /></PrimaryButton></div></div></div><div className="space-y-4"><Card><SectionCardTitle title="Campaign Summary" /><div className="mt-4 space-y-3 text-xs">{[["Campaign Name", "Summer Sale Campaign"], ["Objective", "Sales"], ["Platform", "Google Ads"], ["Type", "Search"], ["Status", "Draft"]].map(([label, value]) => <div className="flex justify-between" key={label}><span className="text-[#7d899e]">{label}</span><strong>{value}</strong></div>)}</div><SecondaryButton className="mt-5 w-full"><Edit3 size={13} />Edit Later</SecondaryButton></Card><Card><SectionCardTitle title="Forecasted Performance" /><div className="mt-4 grid grid-cols-2 gap-4 text-xs"><div><span className="text-[#8490a4]">Est. Clicks</span><strong className="mt-1 block">18K – 24K</strong></div><div><span className="text-[#8490a4]">Est. Conversions</span><strong className="mt-1 block">450 – 620</strong></div><div><span className="text-[#8490a4]">Est. ROAS</span><strong className="mt-1 block">3.2x – 4.1x</strong></div><div><span className="text-[#8490a4]">Est. CPA</span><strong className="mt-1 block">$6.20 – $8.10</strong></div></div></Card></div></div></Card></AppShell>; }

function GenericPage({ title }: { title: string }) { return <AppShell title={title} action={<PrimaryButton><Plus size={15} />Create</PrimaryButton>}><PageHeading title={title} description={`Manage your ${title.toLowerCase()} in one workspace.`} /><div className="grid gap-4 md:grid-cols-3"><MetricCard metric={{ label: `Total ${title}`, value: "24", change: "12.4%", trend: "up", icon: "chart", tone: "purple" }} /><MetricCard metric={{ label: "Active", value: "18", change: "8.3%", trend: "up", icon: "conversions", tone: "green" }} /><MetricCard metric={{ label: "Pending", value: "6", change: "3.2%", trend: "down", icon: "calendar", tone: "orange" }} /></div><Card className="mt-4"><SectionCardTitle title={`All ${title}`} action={<SecondaryButton><Filter size={14} />Filters</SecondaryButton>} /><div className="mt-4 rounded-xl border border-dashed border-[#dfe3eb] p-12 text-center"><span className="mx-auto grid h-12 w-12 place-items-center rounded-xl bg-[#f0eaff] text-[#6940e8]"><FileBarChart size={22} /></span><h3 className="mt-4 text-sm font-extrabold">No {title.toLowerCase()} need your attention</h3><p className="mt-1 text-xs text-[#7d899e]">Create a new item to get started.</p></div></Card></AppShell>; }

export function MarketerApp() { const pathname = usePathname(); const segments = pathname.split("/").filter(Boolean).map(decodeURIComponent); const root = segments[0] || "overview"; const second = segments[1]; if (root === "auth") return <AuthPage mode={(second as "login" | "signup" | "forgot-password" | "reset-password" | "verify-email") || "login"} />; if (root === "onboarding") return <OnboardingPage step={second || "brand"} />; if (root === "overview" || root === "dashboard") return <DynamicOverviewPage />; if (root === "campaigns" && second === "create") return <CampaignWizard />; if (root === "campaigns" && second) return <CampaignDetailPage campaignId={second} />; if (root === "campaigns") return <CampaignsPage />; if (root === "analytics") return <AnalyticsPage />; if (root === "integrations") return <IntegrationsPage detailId={second} />; if (root === "social-media") return <SocialPage />; if (root === "content-studio") return <ContentStudioPage />; if (root === "ai-content-creator") return <AIContentPage />; if (root === "ai-insights") return <AIInsightsPage />; if (root === "leads") return <LeadsPage detailId={second} />; if (root === "ad-manager") return <AdManagerPage />; if (root === "reports") return <ReportsPage />; if (root === "team") return <TeamPage />; if (root === "clients") return <ClientsPage detailId={second} />; if (root === "billing") return <BillingPage />; if (root === "settings") return <SettingsPage subsection={second} />; if (root === "automation") return <AutomationPage />; return <GenericPage title={root === "search" ? "Search" : root === "notifications" ? "Notifications" : "Workspace"} />; }
